import React, { useState, useRef } from 'react';
import {
  Dialog, DialogTitle, DialogContent, DialogActions,
  Button, Box, Typography, Alert, LinearProgress, List, ListItem
} from '@mui/material';
import UploadFileIcon from '@mui/icons-material/UploadFile';
import DownloadIcon from '@mui/icons-material/Download';
import api from '../../../services/api';

const RISK_TEMPLATE_HEADERS = [
  'risk_description', 'category', 'department_id', 'owner',
  'date_reviewed', 'kra_at_risk', 'causes', 'consequence',
  'inherent_likelihood', 'inherent_consequence',
  'existing_controls', 'control_effectiveness',
  'residual_likelihood', 'residual_consequence',
  'mitigation_strategy', 'action_treatment',
  'method', 'resolved_by', 'status',
  'likelihood_justification', 'consequence_justification'
];

const SHE_TEMPLATE_HEADERS = [
  'description', 'activity_category', 'department', 'owner',
  'date', 'quarter', 'location', 'staff_group', 'reference_id',
  'observations', 'recommendations', 'priority', 'status',
  'verification', 'comments'
];

const RISK_SAMPLE = [
  'Failure of critical IT infrastructure', 'Technological', 'Information Technology Services',
  'IT Manager', '2026-05-18', 'Service Delivery', 'Power outage / hardware failure',
  'System downtime and data loss',
  'POSSIBLE', 'MAJOR', 'UPS and backup systems', 'Moderate',
  'UNLIKELY', 'MODERATE', 'Reduce',
  'Implement redundant systems and disaster recovery plan',
  'Risk Monitoring', '2026-08-18', 'Open', 'Based on historical incidents', 'Could affect all departments'
];

const SHE_SAMPLE = [
  'Chemical spillage in laboratory', 'Health & Safety', 'Science Faculty', 'Safety Officer',
  '2026-05-18', 'Q2', 'Science Lab Block A', 'Laboratory Staff', 'REF-2026-001',
  'Improper storage of chemicals observed', 'Relocate chemicals to approved storage',
  'High', 'Open', 'Pending inspection', ''
];

const downloadTemplate = (type) => {
  const headers = type === 'risks' ? RISK_TEMPLATE_HEADERS : SHE_TEMPLATE_HEADERS;
  const sample  = type === 'risks' ? RISK_SAMPLE : SHE_SAMPLE;
  const csv = [headers.join(','), sample.map(v => `"${v}"`).join(',')].join('\r\n');
  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = type === 'risks' ? 'risk_import_template.csv' : 'she_import_template.csv';
  a.click();
  URL.revokeObjectURL(url);
};

const CsvImportDialog = ({ open, onClose, type, onSuccess }) => {
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');
  const inputRef = useRef();

  const endpoint = type === 'risks' ? '/risks/import' : '/she-events/import';
  const label    = type === 'risks' ? 'Risk' : 'SHE';

  const handleFileChange = (e) => {
    setFile(e.target.files[0] || null);
    setResult(null);
    setError('');
  };

  const handleUpload = async () => {
    if (!file) return;
    setUploading(true);
    setError('');
    setResult(null);
    const form = new FormData();
    form.append('file', file);
    try {
      const res = await api.post(endpoint, form, { headers: { 'Content-Type': 'multipart/form-data' } });
      setResult(res.data);
      if (res.data.imported > 0) onSuccess();
    } catch (e) {
      setError(e.response?.data?.error || e.response?.data?.message || 'Upload failed. Check file format.');
    } finally {
      setUploading(false);
    }
  };

  const handleClose = () => {
    setFile(null);
    setResult(null);
    setError('');
    onClose();
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth
      PaperProps={{ sx: { background: '#1e293b', color: 'white', borderRadius: '20px', border: '1px solid rgba(255,255,255,0.1)' } }}>
      <DialogTitle sx={{ fontWeight: 'bold', fontSize: '1.1rem', pb: 1 }}>
        Import {label} Records from CSV
      </DialogTitle>
      <DialogContent>
        <Typography sx={{ color: '#94a3b8', fontSize: '0.82rem', mb: 2 }}>
          Upload a CSV file using the template below. The first row must contain column headers. Required columns are highlighted in the template.
        </Typography>

        <Button
          variant="outlined"
          size="small"
          startIcon={<DownloadIcon />}
          onClick={() => downloadTemplate(type)}
          sx={{ mb: 3, color: '#3b82f6', borderColor: 'rgba(59,130,246,0.4)', textTransform: 'none', borderRadius: '8px', '&:hover': { background: 'rgba(59,130,246,0.08)' } }}
        >
          Download {label} Template CSV
        </Button>

        <Box
          onClick={() => inputRef.current.click()}
          sx={{
            border: '2px dashed rgba(255,255,255,0.15)', borderRadius: '16px', p: 4,
            textAlign: 'center', cursor: 'pointer', mb: 2,
            background: file ? 'rgba(16,185,129,0.06)' : 'rgba(255,255,255,0.02)',
            transition: 'all 0.2s',
            '&:hover': { borderColor: '#3b82f6', background: 'rgba(59,130,246,0.05)' }
          }}
        >
          <UploadFileIcon sx={{ fontSize: 36, color: file ? '#10b981' : '#64748b', mb: 1 }} />
          <Typography sx={{ color: file ? '#10b981' : '#94a3b8', fontSize: '0.9rem', fontWeight: 'bold' }}>
            {file ? file.name : 'Click to select a CSV file'}
          </Typography>
          {file && (
            <Typography sx={{ color: '#64748b', fontSize: '0.75rem', mt: 0.5 }}>
              {(file.size / 1024).toFixed(1)} KB
            </Typography>
          )}
          <input ref={inputRef} type="file" accept=".csv,.txt" style={{ display: 'none' }} onChange={handleFileChange} />
        </Box>

        {uploading && <LinearProgress sx={{ borderRadius: '4px', mb: 2 }} />}

        {error && <Alert severity="error" sx={{ mb: 2, borderRadius: '10px' }}>{error}</Alert>}

        {result && (
          <Box sx={{ p: 2, background: 'rgba(255,255,255,0.04)', borderRadius: '12px', border: '1px solid rgba(255,255,255,0.08)' }}>
            <Typography sx={{ color: '#10b981', fontWeight: 'bold', mb: 1 }}>
              Import complete: {result.imported} imported, {result.skipped} skipped
            </Typography>
            {result.errors?.length > 0 && (
              <List dense disablePadding>
                {result.errors.slice(0, 5).map((e, i) => (
                  <ListItem key={i} disableGutters>
                    <Typography sx={{ color: '#f87171', fontSize: '0.75rem' }}>• {e}</Typography>
                  </ListItem>
                ))}
                {result.errors.length > 5 && (
                  <Typography sx={{ color: '#94a3b8', fontSize: '0.72rem' }}>…and {result.errors.length - 5} more issues</Typography>
                )}
              </List>
            )}
          </Box>
        )}
      </DialogContent>
      <DialogActions sx={{ p: 3, gap: 1 }}>
        <Button onClick={handleClose} sx={{ color: '#94a3b8', textTransform: 'none' }}>Close</Button>
        <Button
          variant="contained"
          onClick={handleUpload}
          disabled={!file || uploading}
          startIcon={<UploadFileIcon />}
          sx={{ background: 'linear-gradient(135deg,#10b981,#059669)', textTransform: 'none', fontWeight: 'bold', borderRadius: '10px', px: 3 }}
        >
          {uploading ? 'Importing...' : 'Import'}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default CsvImportDialog;
